var p = new JobPlatform(2);
Cj.Eq(p.Submit("a", () => 1), true, "first submit accepted");
Cj.Eq(p.Submit("a", () => 1), false, "duplicate rejected");
Cj.Eq(p.Submit("b", () => 1), true, "second slot used");
Cj.Eq(p.Submit("c", () => 1), false, "capacity exceeded");
Cj.Eq(p.Pending, 2, "two jobs pending");

var p = new JobPlatform(20);
var ids = Enumerable.Range(0, 12).Select(i => $"job-{i}").ToList();
var (accepted, rejected, executed) = JobPlatform.SubmitSchedule(p, ids, 2);
Cj.Eq(accepted, 12, "12 unique ids accepted");
Cj.Eq(rejected, 24, "36 deliveries − 12 uniques rejected as duplicates");
Cj.Eq(executed, 12, "each job executed exactly once");
